// One realistic meeting note with clear decisions and owned action items.
return [{ json: {
  Title: 'Q3 launch planning',
  Date: '2026-07-18',
  Notes: `We reviewed the Q3 launch. Decision: we ship the beta on August 15, gated to the first 50 users. `+
    `Sara will finalize the onboarding email sequence by next Friday. Tom owns the pricing page update and will `+
    `have a draft ready before the next standup. We still need someone to write the changelog — unassigned for now. `+
    `Decision: marketing budget stays flat for the quarter. Priya raised that support coverage is thin during the `+
    `launch window; she will draft a coverage plan by end of week.`
}}];

// Read the form submission (or the TEST sample) and build the AI input. Iterates all items.
const MAX = 8000;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let notes = String(j.Notes || j.notes || '').trim();
  if (notes.length > MAX) notes = notes.slice(0, MAX) + ' …[truncated]';
  const title = String(j.Title || j.title || 'Untitled meeting').trim();
  const date = String(j.Date || j.date || '').trim();
  out.push({ json: {
    notes, title, date,
    createdAt: $now.toISO(),
    aiInput: `MEETING TITLE: ${title}\nDATE: ${date || '(not given)'}\n\nNOTES / TRANSCRIPT:\n${notes}`
  }});
}
return out;

// Honest guardrail: coerce arrays and the nested action-items, drop empty tasks, flag malformation.
// Pairs each AI item with its source by position.
const preps = $('Prepare notes').all();
const items = $input.all();
const asArr = v => Array.isArray(v) ? v : (v ? [v] : []);
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = items[i].json;
  const ai = (src && typeof src.output === 'object' && src.output) ? src.output : src;
  const prep = (preps[i] || preps[0] || { json: {} }).json;
  let summary = String(ai.summary || '').trim();
  let decisions = asArr(ai.decisions).map(s => String(s).trim()).filter(Boolean);
  let actionItems = asArr(ai.action_items).map(a => ({
    task: String((a && a.task) || '').trim(),
    owner: String((a && a.owner) || '').trim() || 'unassigned',
    due: String((a && a.due) || '').trim()
  })).filter(a => a.task);
  let lang = String(ai.detected_language || '').trim();
  let malformed = false;
  if (!summary) { summary = '(no summary produced)'; malformed = true; }
  out.push({ json: {
    createdAt: prep.createdAt, meetingTitle: prep.title, meetingDate: prep.date,
    detectedLanguage: lang, summary,
    decisions: decisions.join(' | '),
    actionItems, actionItemCount: actionItems.length,
    needsReview: malformed, version: 'perly-meeting-notes-v1.0'
  }});
}
return out;

// Fan out: one row per action item (or none if the meeting produced no tasks).
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const meta = { createdAt: j.createdAt, meetingTitle: j.meetingTitle, version: j.version };
  for (const a of (Array.isArray(j.actionItems) ? j.actionItems : [])) {
    out.push({ json: { ...meta, task: a.task, owner: a.owner, due: a.due, status: 'open' } });
  }
}
return out;

// Tolerant assertions on the exploded action items + the guardrail summary.
const g = $('Guardrail').first().json;
const rows = $input.all().map(i => i.json);
const problems = [];
if (!g.summary || g.summary.startsWith('(no summary')) problems.push('no summary produced');
if ((g.actionItemCount || 0) < 1) problems.push('no action items extracted');
if (rows.length !== g.actionItemCount) problems.push(`exploded ${rows.length} rows != count ${g.actionItemCount}`);
for (const r of rows) {
  if (!r.task) problems.push('an action item has no task');
  if (!r.owner) problems.push('an action item has no owner');
  if (r.status !== 'open') problems.push('action item status not open');
}
// Un test che fallisce deve FALLIRE, non restituire un oggetto triste che nessuno
// legge. Senza questa riga l'esecuzione resta verde e il pannello di n8n dice che
// è andato tutto bene: esattamente il guasto silenzioso contro cui esiste il test.
if (problems.length) {
  throw new Error(`TEST FAILED (${problems.length}): ` + problems.join(' | '));
}

return [{ json: {
  result: problems.length ? 'FAILED' : 'PASSED',
  summary: g.summary, decisions: g.decisions, actionItems: rows.length,
  tasks: rows.map(r => `${r.task.slice(0,34)} @${r.owner}${r.due ? ' ('+r.due+')' : ''}`),
  problems
}}];
